#ifndef INTERFACES_H
#define INTERFACES_H

#include <atomic>
#include <cstddef>
#include <cstdint>

// Forward declarations
template <typename T> class SPSCRingBuffer; // e.g., moodycamel::ReaderWriterQueue

// Configuration (generated by ML export tool)
namespace Config {
    constexpr int STATE_DIM = 64;          // Example: state dimension of SSM
    constexpr int NUM_LAYERS = 2;          // Number of SSM layers
    constexpr int COND_DIM = 16;           // Conditioning vector dimension
    constexpr int MAX_BLOCK_SIZE = 512;    // Maximum block size for processing
    constexpr int PARAM_COUNT = 32;        // Number of user parameters
}

// === SSM Core Interface ===
// This is the real-time audio processing core.
// All methods called from the audio thread must be lock-free and allocation-free.

class SSMInferenceCore {
public:
    // Pre-allocates working memory for the given max block size.
    // Called from the main thread during activate().
    void initialize(int max_block_size);

    // Resets the internal state to zero.
    // Called from the audio thread (e.g., when note starts) or main thread (preset load).
    void reset();

    // Processes a block of audio in Mode B (block processing).
    // Input and output are interleaved for multiple channels? We assume mono for simplicity.
    // The audio thread calls this with pre-allocated input and output buffers.
    void process_block(const float* input, float* output, int block_size);

    // Processes a single sample (Mode A). Can be called in a loop for micro-blocks.
    void process_sample(float input, float& output);

    // Sets the SSM parameters (delta, B, C) for a layer.
    // Called from the main thread when conditioning updates or weights change.
    // These are stored in atomic memory so the audio thread can read them without locks.
    void set_layer_parameters(int layer, const float* delta, const float* B, const float* C);

    // Sets the conditioning vector (from ARA thread via double buffer).
    // The audio thread will read the latest conditioning vector via an atomic pointer.
    void set_conditioning_vector(const float* cond); // cond is COND_DIM floats

    // Gets the current state (for snapshot). Called by main thread with seqlock.
    void get_state(float* state_buffer) const; // state_buffer must be STATE_DIM * NUM_LAYERS

    // Sets the state (for snapshot). Called by main thread with seqlock.
    void set_state(const float* state_buffer); // state_buffer must be STATE_DIM * NUM_LAYERS

private:
    // Internal state (pre-allocated)
    float* h_state_; // [NUM_LAYERS][STATE_DIM]
    // Temporary buffers (pre-allocated)
    float* temp_buffer_; // size depends on max_block_size and internal needs
    // Parameters (atomic for lock-free reading by audio thread)
    alignas(64) std::atomic<float> delta_atomic_[NUM_LAYERS * STATE_DIM]; // Example layout
    alignas(64) std::atomic<float> B_atomic_[NUM_LAYERS * STATE_DIM * STATE_DIM]; // Simplified
    alignas(64) std::atomic<float> C_atomic_[NUM_LAYERS * STATE_DIM * STATE_DIM];
    // Conditioning vector (double-buffered, managed by ARA thread and main thread)
    // We'll use an atomic pointer to the latest conditioning vector.
    // The actual buffering is managed outside this class (see ADR-001).
    std::atomic<const float*> cond_vector_atomic_;
};

// === Host API Interface (CLAP/ARA) ===
// This is the adapter that connects the SSM core to the host via CLAP and ARA.
// It runs on the main thread and the ARA thread.

class HostAPIAdapter {
public:
    HostAPIAdapter(SSMInferenceCore& ssm_core);
    ~HostAPIAdapter();

    // Called by the host (CLAP) during plugin activation.
    void activate(double sample_rate, int max_block_size);

    // Called by the host (CLAP) during plugin deactivation.
    void deactivate();

    // Audio callback (CLAP). This runs on the audio thread.
    // It delegates to the SSM core.
    void process(const float** inputs, float** outputs, int32_t frames, int32_t channels);

    // CLAP parameter change (called from main thread).
    void on_param_change(int param_index, float value);

    // CLAP note event (called from main thread or audio thread? In CLAP, note events are on the audio thread).
    // We'll assume they are on the audio thread and must be lock-free.
    void on_note_on(int note_number, float velocity, int32_t id, int32_t channel);
    void on_note_off(int note_number, float velocity, int32_t id, int32_t channel);

    // ARA: DocumentController updates (called from ARA thread).
    void update_ara_document_controller(/* ARA specifics */);

    // ARA: PlaybackRenderer (called from ARA thread for offline rendering).
    void render_ara_playback(/* ARA specifics */);

    // ARA: EditorRenderer (called from ARA thread for GUI updates in ARA host).
    void render_ara_editor(/* ARA specifics */);

    // State serialization (called from main thread).
    void serialize_state(/* output stream */);
    void deserialize_state(/* input stream */);

private:
    SSMInferenceCore& ssm_core_;
    // Lock-free queue for parameter changes from main thread to audio thread?
    // Actually, we are using atomic floats for parameters, so we might not need a queue for that.
    // But for note events, we might need to queue them to the audio thread if we cannot process in the ARA thread?
    // However, note events in CLAP are on the audio thread, so we can process them there.
    // We'll leave the internal communication mechanisms to the implementation.
    // For now, we note that the audio thread reads atomic parameters and the conditioning vector.
};

// === ML Pipeline Interface ===
// This is not a runtime interface but a design-time one.
// The ML export tool generates:
//   - config.h (with the constants in Config namespace)
//   - weight file (binary, memory-mappable)
//   - possibly a header for the weight file structure.

// Example weight file header (to be generated by ML export tool)
struct alignas(64) WeightFileHeader {
    uint32_t magic;      // e.g., 0x4D414D42 ('MAMB')
    uint32_t version;    // e.g., 1
    uint32_t state_dim;  // Config::STATE_DIM
    uint32_t num_layers; // Config::NUM_LAYERS
    uint32_t cond_dim;   // Config::COND_DIM
    uint32_t param_count; // Config::PARAM_COUNT
    uint32_t weight_data_size; // Size of the weight data that follows
    // Followed by the weight data (binary blob) for all layers.
};

// === UI/State Interface ===
// This is abstracted by the HostAPIAdapter and the SSMInferenceCore.
// The UI (running on the main thread) will:
//   - Call HostAPIAdapter to change parameters and notes.
//   - Serialize/deserialize state via HostAPIAdapter.
//   - Update the GUI based on plugin state (which it gets from the HostAPIAdapter?)
//     We might need a way for the UI to query the current state (e.g., for metering).
//     But note: the UI must not block the audio thread. We can use lock-free queues to send
//     state updates to the UI thread, or the UI can poll (with caution) atomic variables.

// For simplicity, we assume the UI gets its updates via the same mechanisms as the host:
//   - Parameter changes: the UI sets them via HostAPIAdapter, and the audio thread sees them via atomics.
//   - For other state (e.g., SSM state for display), we might provide a lock-free queue that the
//     audio thread can push to (if the UI wants to visualize the state). However, this is optional.

// We'll leave the UI specifics to the implementation, but note that the UI thread must not
// block the audio thread.

#endif // INTERFACES_H